// Offline navigation must be answered by the precache, including the canonical entry point "/"
// (bead qrcode-to8, tightened by bead qrcode-t6l).
//
// The precache manifest is generated by walking dist/, so on its own it lists file URLs such as
// /index.html and never "/". The install handler therefore adds the navigable entry point
// explicitly (`const urls = ['/', ...manifest.files.map(toPrecacheUrl)]` in app/sw.js).
//
// This file pins both halves of that contract, and the second one depends on the first:
//   1. the install handler really does put "/" in cache.addAll(), first (see `installCalls`);
//   2. the worker's fetch handler resolves a navigation to "/" from the cache it just filled.
// The precached set is not hand-written anywhere: it is whatever install() actually passed to
// addAll(), so dropping "/" from the install list fails both the install assertion and case 1
// below, instead of silently passing against a fixture that still lists "/".
//
// app/sw.js registers its listeners at import time, so the stubs are installed before the dynamic
// import. Each test file runs in its own process (see test/unit/sw-precache.test.mjs).
import test from 'node:test';
import assert from 'node:assert/strict';

const origin = 'https://qr-snapper.test';
const VERSION = '9.9.9-test';
const PRECACHE_CACHE = `qr-precache-${VERSION}`;
const MANIFEST_URL = '/sw-manifest.json';

// What the generated manifest would contain for this release. "/" is absent on purpose: install()
// has to add it, which is the behaviour under test.
const manifestFiles = ['index.html', 'about.html'];

const listeners = new Map();
const shell = new Response('<!doctype html><title>shell</title>', {
  status: 200,
  headers: { 'content-type': 'text/html; charset=utf-8' },
});

/** Every URL install() handed to cache.addAll(), in order. */
let installCalls = [];
/** Manifest fetches are expected; anything else is the network being down. */
let manifestFetches = 0;
let fetchCalls = 0;
let lastMatchOptions = null;

globalThis.__APP_VERSION__ = VERSION;
globalThis.self = {
  location: { origin },
  skipWaiting() {},
  clients: { claim() { return Promise.resolve(); } },
  registration: { unregister() { return Promise.resolve(true); } },
  addEventListener(type, handler) { listeners.set(type, handler); },
};

globalThis.caches = {
  async keys() { return [PRECACHE_CACHE]; },
  async delete() { return true; },
  async open() {
    return {
      async addAll(urls) { installCalls = [...urls]; },
      async keys() { return []; },
    };
  },
  async match(request, options = {}) {
    lastMatchOptions = options;
    const url = new URL(typeof request === 'string' ? request : request.url);
    if (options.cacheName !== PRECACHE_CACHE) return undefined;
    // Cache.match with ignoreSearch matches on the pathname only. The set it searches is what
    // install() actually cached, so this can only answer for URLs that went through addAll().
    const key = options.ignoreSearch ? url.pathname : `${url.pathname}${url.search}`;
    return precached.has(key) ? shell.clone() : undefined;
  },
};

// Network down, apart from the precache manifest the install handler has to read. Any other
// fetch() must be visible as a failure, not a silent success.
globalThis.fetch = async (url) => {
  const target = String(typeof url === 'string' ? url : url.url);
  if (target === MANIFEST_URL) {
    manifestFetches++;
    return new Response(JSON.stringify({ version: VERSION, files: manifestFiles }), {
      status: 200,
      headers: { 'content-type': 'application/json' },
    });
  }
  fetchCalls++;
  throw new TypeError(`network unavailable: ${target}`);
};

await import('../../app/sw.js');
const onFetch = listeners.get('fetch');
assert.ok(onFetch, 'app/sw.js must register a fetch listener');

// Run the real install handler before any navigation, so the precached set comes from app/sw.js
// rather than from this file.
{
  const onInstall = listeners.get('install');
  assert.ok(onInstall, 'app/sw.js must register an install listener');
  let lifetime;
  onInstall({ waitUntil(promise) { lifetime = promise; } });
  assert.ok(lifetime, 'the install handler must hold its work with waitUntil');
  await lifetime;
}

/** The precached pathnames, exactly as install() shipped them. */
const precached = new Set(installCalls.map((url) => new URL(url, origin).pathname));

/**
 * Dispatch a synthetic navigation through the worker's fetch listener and return the response the
 * router passed to respondWith().
 * @param {string} url
 */
async function navigate(url) {
  const request = new Request(url);
  // node's undici refuses mode 'navigate' in the Request constructor; the route only reads the
  // property, so shadowing it keeps the test honest about what the worker sees.
  Object.defineProperty(request, 'mode', { value: 'navigate' });

  let responded;
  onFetch({ request, respondWith(promise) { responded = promise; } });
  assert.ok(responded, 'a same-origin navigation must be answered by the worker');

  return responded;
}

test('install precaches the navigable entry point "/" ahead of the manifest entries', () => {
  assert.equal(manifestFetches, 1, 'the manifest is fetched exactly once');
  assert.equal(installCalls[0], '/', '"/" is the navigable entry point and goes first');
  assert.deepEqual(
    installCalls.slice(1).map((url) => new URL(url, origin).pathname),
    ['/index.html', '/about.html'],
    'the manifest files follow it, resolved onto this origin'
  );
  assert.ok(precached.has('/'), 'the request side below can only match what was precached');
});

test('a navigation to / resolves from the precache with the network down', async () => {
  fetchCalls = 0;
  const response = await navigate(`${origin}/`);

  assert.equal(response.status, 200, 'offline navigation to the entry point must not fail');
  assert.equal(await response.text(), '<!doctype html><title>shell</title>');
  assert.equal(fetchCalls, 0, 'a precached navigation must not touch the network at all');
  assert.equal(lastMatchOptions.cacheName, PRECACHE_CACHE, 'only this release cache may answer');
  assert.equal(lastMatchOptions.ignoreSearch, true);
});

test('a navigation to / with a shared-link query still matches the precached entry point', async () => {
  fetchCalls = 0;
  const response = await navigate(`${origin}/?utm_source=shared`);

  assert.equal(response.status, 200);
  assert.equal(fetchCalls, 0, 'ignoreSearch must keep shared links working offline');
});

test('the precached file URLs serve offline navigations too', async () => {
  for (const path of ['/index.html', '/about.html']) {
    fetchCalls = 0;
    const response = await navigate(`${origin}${path}`);
    assert.equal(response.status, 200, `${path} must be served from the precache`);
    assert.equal(fetchCalls, 0);
  }
});

// Deliberate decision, not an oversight (bead qrcode-to8): there is no navigate-fallback that
// hands an unknown path the app shell, so an uncached path still fails offline. If such a fallback
// is ever added on purpose, this case has to be rewritten rather than treated as a regression.
test('a path that was never precached still rejects offline, so "/" being precached is the fix', async () => {
  fetchCalls = 0;
  await assert.rejects(navigate(`${origin}/no-such-page`), /network unavailable/);
  assert.equal(fetchCalls, 1, 'an uncached path falls through to the network exactly once');
});
